const total = pm.response.headers.get("Ratelimit-Limit") + 10;     
let counter = 0;

function send() {
    pm.sendRequest({
        url: pm.request.url.toString(),
        method: pm.request.method,
    }, (err, res) => {

        counter++;

        if (res.code === 429) {
            console.log("429 пойман");
            console.log("Ratelimit-Reset:", res.headers.get("Ratelimit-Reset"));
            console.log("Ratelimit-Policy:", res.headers.get("Ratelimit-Policy"));
            console.log("Ratelimit-Limit:", res.headers.get("Ratelimit-Limit"));
            return; 
        }
        if (counter < total) send();  
    });
}

send();

